export function defaultFormlyConfig(config: FormlyConfig): ConfigOption {
  return {
    types: [
      { name: 'formly-group', component: FormlyGroup },
      { name: 'formly-template', component: FormlyTemplateType },
    ],
    extensions: [
      { name: 'core', extension: new CoreExtension(config), priority: -250 },
      { name: 'field-validation', extension: new FieldValidationExtension(config), priority: -200 },
      { name: 'field-form', extension: new FieldFormExtension(), priority: -150 },
      { name: 'field-expression', extension: new FieldExpressionExtension(), priority: -100 },
    ],
  };
}

@NgModule({
  declarations: [
    FormlyTemplate,
    FormlyForm,
    FormlyField,
    FormlyAttributes,
    FormlyGroup,
    FormlyValidationMessage,
    FormlyTemplateType,
  ],
  exports: [FormlyTemplate, FormlyForm, FormlyField, FormlyAttributes, FormlyGroup, FormlyValidationMessage],
  imports: [CommonModule],
})
export class FormlyModule {
  static forRoot(config: ConfigOption = {}): ModuleWithProviders<FormlyModule> {
    return {
      ngModule: FormlyModule,
      providers: [
        { provide: FORMLY_CONFIG, multi: true, useFactory: defaultFormlyConfig, deps: [FormlyConfig] },
        { provide: FORMLY_CONFIG, useValue: config, multi: true },
        FormlyConfig,
        FormlyFormBuilder,
      ],
    };
  }

  static forChild(config: ConfigOption = {}): ModuleWithProviders<FormlyModule> {
    return {
      ngModule: FormlyModule,
      providers: [
        { provide: FORMLY_CONFIG, multi: true, useFactory: defaultFormlyConfig, deps: [FormlyConfig] },
        { provide: FORMLY_CONFIG, useValue: config, multi: true },
        FormlyFormBuilder,
      ],
    };
  }

  constructor(configService: FormlyConfig, @Optional() @Inject(FORMLY_CONFIG) configs: ConfigOption[] = []) {
    if (!configs) {
      return;
    }

    configs.forEach((config) => configService.addConfig(config));
  }
}

export class FormlyFormBuilder {
  constructor(
    private config: FormlyConfig,
    private injector: Injector,
    @Optional() private viewContainerRef: ViewContainerRef,
    @Optional() private parentForm: FormGroupDirective,
  ) {}

  buildForm(form: FormGroup | FormArray, fieldGroup: FormlyFieldConfig[] = [], model: any, options: FormlyFormOptions) {
    this.build({ fieldGroup, model, form, options });
  }

  build(field: FormlyFieldConfig) {
    if (!this.config.extensions.core) {
      throw new Error('NgxFormly: missing `forRoot()` call. use `forRoot()` when registering the `FormlyModule`.');
    }

    if (!field.parent) {
      this._setOptions(field);
    }

    disableTreeValidityCall(field.form, () => {
      this._build(field);
      // TODO: add test for https://github.com/ngx-formly/ngx-formly/issues/3910
      if (!field.parent || (field as FormlyFieldConfigCache).fieldArray) {
        // detect changes early to avoid reset value by hidden fields
        const options = (field as FormlyFieldConfigCache).options;

        if (field.parent && isHiddenField(field)) {
          // when hide is used in expression set defaul value will not be set until detect hide changes
          // which causes default value not set on new item is added
          options._hiddenFieldsForCheck?.push({ field, default: false });
        }

        options.checkExpressions?.(field, true);
        options._detectChanges?.(field);
      }
    });
  }

  private _build(field: FormlyFieldConfigCache) {
    if (!field) {
      return;
    }

    const extensions = Object.values(this.config.extensions);
    extensions.forEach((extension) => extension.prePopulate?.(field));
    extensions.forEach((extension) => extension.onPopulate?.(field));
    field.fieldGroup?.forEach((f) => this._build(f));
    extensions.forEach((extension) => extension.postPopulate?.(field));
  }

  private _setOptions(field: FormlyFieldConfigCache) {
    field.form = field.form || new FormGroup({});
    field.model = field.model || {};
    field.options = field.options || {};
    const options = field.options;

    if (!options._viewContainerRef) {
      defineHiddenProp(options, '_viewContainerRef', this.viewContainerRef);
    }

    if (!options._injector) {
      defineHiddenProp(options, '_injector', this.injector);
    }

    if (!options.build) {
      options._buildForm = () => {
        console.warn(`Formly: 'options._buildForm' is deprecated since v6.0, use 'options.build' instead.`);
        this.build(field);
      };

      options.build = (f: FormlyFieldConfig = field) => {
        this.build(f);

        return f;
      };
    }

    if (!options.parentForm && this.parentForm) {
      defineHiddenProp(options, 'parentForm', this.parentForm);

      if (!isSignalRequired()) {
        observe(options, ['parentForm', 'submitted'], ({ firstChange }) => {
          if (!firstChange) {
            options.detectChanges(field);
          }
        });
      }
    }
  }
}

# Formly Field Presets
With formly templates, wrappers and extensions, it's easy to reuse form logic throughout your app. However, in larger projects, you will often find yourself defining the same things over and over; think of common form fields like email, name or password fields which should be the same throughout your app.

The `@ngx-formly/core/preset` enables you to define reusable `FormlyFieldConfig`s centrally. 

## Defining a Preset
To define a preset, two steps are necessary:
- Importing the `FormlyPresetModule` 
- Providing presets to `FormlyConfig`

Have a look at the following example which defines a simple `firstName` preset:

```typescript
@NgModule({
  imports: [
    ...
    FormlyPresetModule,
    FormlyModule.forRoot({
      presets: [
        {
          name: 'firstName',
          config: {
            key: 'firstName',
            type: 'input',
            props: {
              label: 'First Name',
            },
          },
        },
      ],
    }),
  ],
})
export class AppModule {}

```

It is also possible to define more complex presets by using a `FormlyFieldConfigPresetProvider` (which contains only a single `getConfiguration` method). This enables presets that contain dependencies and can be self-configuring.
Refer to [Example: Presets](https://formly.dev/examples/other/presets) to see this behavior in action.

## Using Presets
After you have defined a preset, it's very easy to use them in your forms. Presets are accessed using so-called *pseudo-types*, which are prefixed with a single `#`:

```typescript
fieldConfig = [
  ...
  {
    type: '#firstName'
  }
]
```

This will substitute all properties with those defined in the preset. 

To reuse fields while overriding only certain properties, simply specify those properties:

```typescript
fieldConfig = [
  ...
  {
    type: '#firstName'
    props: {
      label: 'alternative label'
    }
  }
]
```

# Custom Extensions

Extensions are a versatile formly feature that allows you to implement cross-cutting functionality that can be applied to all of your fields.

Internally, a lot of formly's logic is built on extensions, so understanding them can greatly increase the things you can do with formly. If you're looking for more resources and examples, check out these links:
- [Egghead.io courses on extensions](https://egghead.io/lessons/angular-implement-cross-cutting-functionality-with-angular-formly-extensions)
- [Example: using an extension to internationalize forms](https://formly.dev/examples/advanced/i18n-alternative)
- [Example: using an extension to include animations in forms](https://formly.dev/examples/other/hide-fields-with-animations)


## Creating a Custom Extension

Creating a custom extension is easy. The following example creates an extension that defines a default label if the `FormlyFieldConfig` doesn't define one itself.

See live demo: [demo](https://stackblitz.com/edit/ngx-formly-ui-bootstrap-slzm3p?file=src/app/app.component.ts)

  ### 1. Define the custom extension:

  There are two options when writing an extension:
  - Create an object of type `FormlyExtension`.
  - Create a class implementing the interface `FormlyExtension`. Do this if your [extension comes with any dependencies](https://formly.dev/examples/advanced/i18n-alternative).

  For this simple example, we will choose the first option.

  ```typescript
  // default-label-extension.ts
  import { FormlyExtension } from '@ngx-formly/core';

  export const defaultLabelExtension: FormlyExtension = {
    prePopulate(field): void {
      if (field.props?.label) {
        return;
      }
      field.props = {
        ...field.props,
        label: 'Default Label'
      }
    },
  };
  ```

:::note

`FormlyExtension` allows you to define up to three methods that will be called in this order during the form construction process:
1. `prePopulate`
2. `onPopulate`
3. `postPopulate`

:::

  ### 2. Register the custom extension in `NgModule` declaration:

  ```typescript
  // app.module.ts
  import { NgModule } from '@angular/core';
  import { BrowserModule } from '@angular/platform-browser';
  import { ReactiveFormsModule } from '@angular/forms';

  import { FormlyModule } from '@ngx-formly/core';
  import { FormlyBootstrapModule } from '@ngx-formly/bootstrap';

  import { AppComponent } from './app.component';
  import { defaultLabelExtension } from './default-label-extension';

  @NgModule({
    imports: [
      BrowserModule,
      ReactiveFormsModule,
      FormlyBootstrapModule,
      FormlyModule.forRoot({
        extensions: [
          {
            name: 'default-label',
            extension: defaultLabelExtension
          }
        ]
      })
    ],
    declarations: [AppComponent],
    bootstrap: [AppComponent]
  })
  export class AppModule {}
  ```

  `extensions: [ ... ]` is where we define which extensions should be active.

  ### 3. Create a custom FormlyFieldConfig and see the magic happen:

  ```typescript
  fields: FormlyFieldConfig[] = [
    {
      key: 'input',
      type: 'input',
      props: {
        label: 'Basic Input'
      }
    },
    {
      key: 'input2',
      type: 'input'
    }
  ];
  ```

  Look at the demo to see that the default label has been automatically added to the field.

## Extension priority
When registering an extension with the `FormlyModule`, you can provide an additional `priority` property of type `number`.
This will be used to change the order in which extensions are executed. If you have multiple extensions that change the same properties of a `FormlyFieldConfig`, you can use this to ensure they are executed in the correct order. Extensions with higher `priority` values will be executed later.

If you don't provide a `priority` option, a default value of `1` will be used. <br/>
Formly's own internal extensions have a priority of `<= -1`.

```typescript
  FormlyModule.forRoot({
    extensions: [
      {
        name: 'default-label',
        extension: defaultLabelExtension,
        priority: 3
      }
    ]
  })
```

private setSortedExtensions(extensionOptions: ExtensionOption[]) {
  // insert new extensions, grouped by priority
  extensionOptions.forEach((extensionOption) => {
    const priority = extensionOption.priority ?? 1;
    this.extensionsByPriority[priority] = {
      ...this.extensionsByPriority[priority],
      [extensionOption.name]: extensionOption.extension,
    };
  });
  // flatten extensions object with sorted keys
  this.extensions = Object.keys(this.extensionsByPriority)
    .map(Number)
    .sort((a, b) => a - b)
    .reduce(
      (acc, prio) => ({
        ...acc,
        ...this.extensionsByPriority[prio],
      }),
      {},
    );
}

import { FormlyConfig, FormlyExtension, FormlyFieldConfig, ɵreverseDeepMerge } from '@ngx-formly/core';
export class PresetSubstitutionExtension implements FormlyExtension {
  constructor(private formlyConfig: FormlyConfig) {}

  prePopulate(field: FormlyFieldConfig): void {
    if (!(typeof field.type === 'string') || field.type[0] !== '#') {
      return;
    }
    const configId = new RegExp(/^#(.+)$/).exec(field.type)?.[1];
    const preset = this.formlyConfig.presets[configId];

    const { type: _, ...fieldConfigWithoutType } = field;
    if (preset) {
      const merged = ɵreverseDeepMerge(
        fieldConfigWithoutType,
        'getConfiguration' in preset ? preset.getConfiguration() : preset,
      );
      Object.assign(field, merged);
    }
  }
}

export function registerLibraryConfigReplacementExtension(formlyConfig: FormlyConfig) {
  return {
    extensions: [
      {
        name: 'libraryConfigReplacement',
        extension: new PresetSubstitutionExtension(formlyConfig),
        priority: -300,
      },
    ],
  };
}
